      phone: '+1 (202) 555-0142',
      message: 'Duplicate submission for testing',
      source: 'portfolio-demo',
    },
  },
];

const items = $input.all();

return items.map((item) => {
  const original = item.json || {};
  const normalized = {
    name: String(original.name ?? '').trim().replace(/\s+/g, ' '),
    email: String(original.email ?? '').trim().toLowerCase(),
    phone: String(original.phone ?? '').replace(/\D/g, ''),
    message: String(original.message ?? '').trim(),
  };
  const valid = Boolean(normalized.name && (normalized.email || normalized.phone));

  return {
    json: {
      ...original,
      normalized,
      valid,
      validationError: valid ? null : 'Name and email or phone are required',
    },
  };
});

const seen = new Set();

return $input.all().map((item) => {
  const json = item.json || {};
  const normalized = json.normalized || {};
  const keys = [
    normalized.email ? 'email:' + normalized.email : '',
    normalized.phone ? 'phone:' + normalized.phone : '',
  ].filter(Boolean);
  const duplicate = Boolean(json.valid && keys.some((key) => seen.has(key)));

  if (json.valid && !duplicate) {
    keys.forEach((key) => seen.add(key));
  }

  return {
    json: {
      ...json,
      duplicate,
      duplicateReason: duplicate ? 'email_or_phone_seen_in_this_run' : null,
    },
  };
});

return $input.all().map((item) => {
  const json = item.json || {};
  let api;

  if (!json.valid) {
    api = { status: 'rejected_invalid', recordId: null, externalRequest: false };
  } else if (json.duplicate) {
    api = { status: 'skipped_duplicate', recordId: null, externalRequest: false };
  } else {
    api = {
      status: 'created_demo',
      recordId: 'DEMO-' + String(json.id || 'new').toUpperCase(),
      externalRequest: false,
    };
  }

  return { json: { ...json, api } };
});

return $input.all().map((item) => {
  const json = item.json || {};
  const status = json.api?.status || 'unknown';
  let text;

  if (status === 'created_demo') {
    text = 'New demo enquiry ' + json.id + ' from ' + json.normalized.name + ' is ready for review.';
  } else if (status === 'skipped_duplicate') {
    text = 'Duplicate demo enquiry ' + json.id + ' was skipped.';
  } else {
    text = 'Demo enquiry ' + json.id + ' was rejected: ' + (json.validationError || 'unknown validation error') + '.';
  }

  return {
    json: {
      ...json,
      telegram: {
        send: false,
        destination: 'not_configured',
        text,
      },
    },
  };
});
